33	/** Inserts one issue directly through the repository, bypassing the service. */
34	async function insertIssue(
35	  tenant: Tenant,
36	  overrides: Partial<{ title: string; assigneeId: (typeof tenant.userIds)["member"] | null }> = {},
37	) {
38	  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
39	  return issueRepo.insertIssue(
