72	    await issueRepo.archiveIssue(north.org.id, issue.id);
73	
74	    const page = await issueRepo.listIssues({
75	      orgId: north.org.id,
76	      limit: 100,
77	      cursor: null,
78	    });
79	
80	    expect(page.items.map((row) => row.id)).not.toContain(issue.id);
81	  });
82	
83	  it("returns archived issues when the scope asks for them", async () => {
84	    const issue = await insertIssue(north, { title: "Also archived" });
85	    await issueRepo.archiveIssue(north.org.id, issue.id);
86	
87	    const page = await issueRepo.listIssues({
88	      orgId: north.org.id,
89	      limit: 100,
90	      cursor: null,
91	      includeArchived: true,
92	    });
93	
94	    expect(page.items.map((row) => row.id)).toContain(issue.id);
95	  });
96	
97	  it("applies status, priority, assignee and label filters together", async () => {
98	    const label = await labelRepo.insertLabel({
99	      orgId: north.org.id,
100	      name: "urgent-bug",
101	      color: "#ef4444",
102	      description: null,
103	    });
104	
105	    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
106	    const matching = await issueRepo.insertIssue(
107	      {
108	        ...issueInput(north.org.id, north.project.id, {
109	          title: "Matches every filter",
110	          assigneeId: north.userIds.member,
111	        }),
112	        status: "in_progress",
113	        priority: "urgent",
114	        labelIds: [label.id],
115	      },
116	      north.userIds.owner,
117	      number,
118	    );
119	
120	    // A near-identical issue that only differs by status must not match.
121	    const otherNumber = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
122	    await issueRepo.insertIssue(
123	      {
124	        ...issueInput(north.org.id, north.project.id, {
125	          title: "Wrong status",
126	          assigneeId: north.userIds.member,
127	        }),
128	        status: "backlog",
129	        priority: "urgent",
130	        labelIds: [label.id],
131	      },
132	      north.userIds.owner,
133	      otherNumber,
134	    );
135	
136	    const page = await issueRepo.listIssues({
137	      orgId: north.org.id,
138	      limit: 100,
139	      cursor: null,
140	      status: ["in_progress"],
141	      priority: ["urgent"],
142	      assigneeId: north.userIds.member,
143	      labelIds: [label.id],
144	    });
145	
146	    expect(page.items.map((row) => row.id)).toEqual([matching.id]);
147	  });
148	
149	  it("pages with a cursor and reports the total", async () => {
150	    const org = await createTenant("pager-issues");
