/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Every status that is not closed — what the `open` filter group expands to. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

/** The two status groups the filter vocabulary accepts alongside real statuses. */
export type IssueStatusGroup = "open" | "closed";

export const ISSUE_STATUS_GROUPS: readonly IssueStatusGroup[] = ["open", "closed"];

/**
 * Expands `open`/`closed` group tokens into their member statuses and drops
 * anything that is neither a known status nor a known group. The URL codec
 * and the filter schema both call this so `status=open` means the same
 * thing wherever it is read.
 */
export function expandIssueStatusFilter(
  values: readonly string[],
): readonly IssueStatus[] {
  const expanded = new Set<IssueStatus>();
  for (const value of values) {
    if (value === "open") {
      for (const status of OPEN_ISSUE_STATUSES) expanded.add(status);
    } else if (value === "closed") {
      for (const status of CLOSED_ISSUE_STATUSES) expanded.add(status);
    } else if ((ISSUE_STATUSES as readonly string[]).includes(value)) {
      expanded.add(value as IssueStatus);
    }
  }
  return [...expanded];
}

export type IssuePriority = "none" | "low" | "medium" | "high" | "urgent";

