1	/**
2	 * Streams the issue CSV; requires the `csv_export` flag.
3	 *
4	 * Owner D. Query parameters are parsed with `exportIssuesSchema` — the same
5	 * schema the export UI submits — so `?includeArchived=true` cannot mean one
6	 * thing in the form and another here.
7	 *
8	 * Must call (do not reimplement): can, isEnabled, toCsv
9	 */
10	
11	import { PENDING_ISSUE_ID, PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
12	import { errorResponse, failure } from "@/app/api/_lib/responses";
13	import { getActor } from "@/lib/actor";
14	import { csvResponseHeaders, toCsv } from "@/lib/csv";
15	import { isEnabled } from "@/lib/feature-flags";
16	import { can } from "@/lib/permissions";
17	import { exportIssuesSchema } from "@/schemas/export";
18	import { buildFlagContext } from "@/server/services/feature-flag-service";
19	import { listIssues } from "@/server/services/issue-service";
20	import { getOrganizationSummary } from "@/server/services/organization-service";
21	import type { Issue } from "@/types/issue";
22	
23	export const dynamic = "force-dynamic";
24	
25	const EXPORT_PAGE_LIMIT = 100;
26	
27	const COLUMNS: readonly string[] = [
28	  "number",
29	  "title",
30	  "status",
31	  "priority",
32	  "assigneeId",
33	  "authorId",
34	  "dueAt",
35	  "createdAt",
36	  "updatedAt",
37	];
38	
39	export async function GET(request: Request): Promise<Response> {
40	  try {
41	    const url = new URL(request.url);
42	    const orgSlug = url.searchParams.get("orgSlug");
43	    if (orgSlug === null) {
44	      return failure("validation_failed", "orgSlug is required.");
45	    }
46	
47	    const actor = await getActor(orgSlug);
48	    const { organization } = await getOrganizationSummary(actor, actor.orgId);
49	
50	    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
51	      return failure("forbidden", "CSV export is not included in this plan.");
52	    }
53	
54	    const allowed = can(actor, "issue:read", {
55	      kind: "issue",
56	      orgId: actor.orgId,
57	      projectId: PENDING_PROJECT_ID,
58	      issueId: PENDING_ISSUE_ID,
59	      authorId: actor.userId,
60	      assigneeId: actor.userId,
61	    });
62	    if (!allowed) {
63	      return failure("forbidden", "You cannot export issues in this organization.");
64	    }
65	
66	    const parsed = exportIssuesSchema.safeParse({
67	      orgId: actor.orgId,
68	      projectId: url.searchParams.get("projectId") ?? undefined,
69	      includeArchived: url.searchParams.get("includeArchived") ?? false,
70	      format: url.searchParams.get("format") ?? "csv",
71	    });
72	    if (!parsed.success) {
73	      return failure("validation_failed", "Bad export parameters.");
74	    }
75	
76	    const page = await listIssues(actor, {
77	      orgId: parsed.data.orgId,
78	      projectId: parsed.data.projectId,
79	      includeArchived: parsed.data.includeArchived,
80	      limit: EXPORT_PAGE_LIMIT,
81	    });
82	
83	    if (parsed.data.format === "json") {
84	      return Response.json({ items: page.items, total: page.total });
85	    }
86	
87	    const csv = toCsv(page.items.map(toRow), COLUMNS);
88	    return new Response(csv, {
89	      headers: csvResponseHeaders(`taskflow-issues-${organization.slug}.csv`),
90	    });
91	  } catch (error) {
92	    return errorResponse(error);
93	  }
94	}
95	
96	/** Flattens an `Issue` into the scalar row shape `toCsv` accepts. */
