import { describe, expect, it } from "vitest";
import { parseIssueFilterParams, issueFilterToParams } from "@/hooks/issue-filter-params";
import { issueFilterSchema } from "@/schemas/issue";

function params(query: string): URLSearchParams {
  return new URLSearchParams(query);
}

describe("sanity", () => {
  it("status=open expands via codec", () => {
    const filter = parseIssueFilterParams(params("status=open"));
    expect(filter.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
  });

  it("status=open is accepted and expanded by the schema directly", () => {
    const parsed = issueFilterSchema.parse({ orgId: "01HZZZZZZZZZZZZZZZZZZZZZZZ", status: ["open"] });
    expect(parsed.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
  });

  it("archived=only parses to archivedOnly", () => {
    const filter = parseIssueFilterParams(params("archived=only"));
    expect(filter.archivedOnly).toBe(true);
    expect(filter.includeArchived).toBeUndefined();
    expect(issueFilterToParams(filter).archived).toBe("only");
  });

  it("due_before accepts a calendar date and converts to next-midnight exclusive bound", () => {
    const parsed = issueFilterSchema.parse({
      orgId: "01HZZZZZZZZZZZZZZZZZZZZZZZ",
      dueBefore: "2026-03-15",
    });
    expect(parsed.dueBefore).toBe("2026-03-16T00:00:00.000Z");
  });

  it("due_before accepts a full timestamp unchanged", () => {
    const parsed = issueFilterSchema.parse({
      orgId: "01HZZZZZZZZZZZZZZZZZZZZZZZ",
      dueBefore: "2026-03-15T12:00:00.000Z",
    });
    expect(parsed.dueBefore).toBe("2026-03-15T12:00:00.000Z");
  });

  it("due_before rejects garbage", () => {
    const result = issueFilterSchema.safeParse({
      orgId: "01HZZZZZZZZZZZZZZZZZZZZZZZ",
      dueBefore: "not-a-date",
    });
    expect(result.success).toBe(false);
  });

  it("assigneeId accepts the me token", () => {
    const parsed = issueFilterSchema.parse({
      orgId: "01HZZZZZZZZZZZZZZZZZZZZZZZ",
      assigneeId: "me",
    });
    expect(parsed.assigneeId).toBe("me");
  });

  it("assigneeId still accepts null for unassigned", () => {
    const parsed = issueFilterSchema.parse({
      orgId: "01HZZZZZZZZZZZZZZZZZZZZZZZ",
      assigneeId: null,
    });
    expect(parsed.assigneeId).toBeNull();
  });
});

