import { afterAll, beforeAll, describe, expect, it } from "vitest";

vi_mock();
function vi_mock() {}

import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("scratch-repo");
});

afterAll(() => {
  cleanup();
});

describe("scratch repo checks", () => {
  it("label filter is all-of, not any-of", async () => {
    const bug = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "bug", color: "#ef4444", description: null });
    const regression = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "regression", color: "#111111", description: null });

    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const both = await issueRepo.insertIssue(
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "has both" }), labelIds: [bug.id, regression.id] },
      tenant.userIds.owner,
      n1,
    );

    const n2 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue(
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "has only bug" }), labelIds: [bug.id] },
      tenant.userIds.owner,
      n2,
    );

    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      labelIds: [bug.id, regression.id],
    });

    expect(page.items.map((i) => i.id)).toEqual([both.id]);
    expect(page.total).toBe(1);
  });

  it("assignee null means unassigned, undefined means anyone", async () => {
    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const unassigned = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "unassigned one", assigneeId: null }),
      tenant.userIds.owner,
      n1,
    );
    const n2 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "assigned one", assigneeId: tenant.userIds.member }),
      tenant.userIds.owner,
      n2,
    );

    const unassignedPage = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      assigneeId: null,
    });
    expect(unassignedPage.items.map((i) => i.id)).toContain(unassigned.id);
    expect(unassignedPage.items.every((i) => i.assigneeId === null)).toBe(true);

    const anyonePage = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });
    expect(anyonePage.total).toBeGreaterThanOrEqual(2);
  });

  it("archivedOnly lists archived rows only", async () => {
    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const live = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "stays live" }),
      tenant.userIds.owner,
      n1,
    );
    const n2 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const toArchive = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "gets archived" }),
      tenant.userIds.owner,
      n2,
    );
    await issueRepo.archiveIssue(tenant.org.id, toArchive.id);

    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      archivedOnly: true,
    });

    const ids = page.items.map((i) => i.id);
    expect(ids).toContain(toArchive.id);
    expect(ids).not.toContain(live.id);
  });

  it("due_before as a calendar date includes the whole day", async () => {
    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const dueThatDay = await issueRepo.insertIssue(
      {
        ...issueInput(tenant.org.id, tenant.project.id, { title: "due midday" }),
        dueAt: "2026-03-15T18:00:00.000Z" as never,
      },
      tenant.userIds.owner,
      n1,
    );

    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      // simulate what the schema would produce for due_before=2026-03-15
      dueBefore: "2026-03-16T00:00:00.000Z" as never,
    });

    expect(page.items.map((i) => i.id)).toContain(dueThatDay.id);
  });
});

